def t(key: str, language: str) -> str:
    return TEXT[language][key]


def collect_ui_translation_keys(project_root: str | Path | None = None) -> set[str]:
    """Collect literal ``t("key", ...)`` calls from every UI source file."""
    root = Path(project_root) if project_root is not None else Path(__file__).resolve().parents[2]
    sources = [root / "agentlab_ui.py", root / "streamlit_app.py"]
    sources.extend(sorted((root / "app" / "ui").rglob("*.py")))
    keys: set[str] = set()
    for source in sources:
        if not source.is_file():
            continue
        tree = ast.parse(source.read_text(encoding="utf-8"), filename=str(source))
        for node in ast.walk(tree):
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "t":
                if node.args and isinstance(node.args[0], ast.Constant) and isinstance(node.args[0].value, str):
                    keys.add(node.args[0].value)
    return keys


def validate_ui_translations(project_root: str | Path | None = None) -> None:
    """Fail early with all missing UI keys before a Streamlit page renders."""
    referenced = collect_ui_translation_keys(project_root)
    missing_zh = sorted(referenced - set(TEXT["zh"]))
    missing_en = sorted(referenced - set(TEXT["en"]))
    if missing_zh or missing_en:
        parts = []
        if missing_zh:
            parts.append("Missing zh translations:\n- " + "\n- ".join(missing_zh))
        if missing_en:
            parts.append("Missing en translations:\n- " + "\n- ".join(missing_en))
        raise RuntimeError("\n".join(parts))


